#include "CommandEventRegistry.h"
CommandEventRegistry::CommandEventRegistry():mappings_{},size_(0U),locked_(false){}RuntimeIntegrationResult CommandEventRegistry::registerMapping(const CommandEventMapping& m){if(locked_)return RuntimeIntegrationResult::REGISTRY_LOCKED;if(!m.isValid())return RuntimeIntegrationResult::INVALID_INPUT;if(find(m.status(),m.errorCode())!=nullptr)return RuntimeIntegrationResult::DUPLICATE_MAPPING;if(size_>=COMMAND_EVENT_MAX_MAPPINGS)return RuntimeIntegrationResult::REGISTRY_FULL;mappings_[size_++]=m;return RuntimeIntegrationResult::SUCCESS;}const CommandEventMapping* CommandEventRegistry::find(ExecutionStatus s,CommandErrorCode e)const{for(size_t i=0U;i<size_;++i)if(mappings_[i].status()==s&&mappings_[i].errorCode()==e)return &mappings_[i];return nullptr;}const CommandEventMapping* CommandEventRegistry::at(size_t i)const{return i<size_?&mappings_[i]:nullptr;}size_t CommandEventRegistry::size()const{return size_;}size_t CommandEventRegistry::capacity()const{return COMMAND_EVENT_MAX_MAPPINGS;}bool CommandEventRegistry::isLocked()const{return locked_;}RuntimeIntegrationResult CommandEventRegistry::lock(){locked_=true;return RuntimeIntegrationResult::SUCCESS;}
